#include <stdio.h>

#define CAP 4
static int q[CAP];
static int front = 0, rear = 0;

static int is_empty(void) { return front == rear; }
static int is_full(void)  { return (rear + 1) % CAP == front; }

static int enqueue(int v) {
    if (is_full()) return 0;
    q[rear] = v;
    rear = (rear + 1) % CAP;
    return 1;
}
static int dequeue(int *v) {
    if (is_empty()) return 0;
    *v = q[front];
    front = (front + 1) % CAP;
    return 1;
}

int main(void) {
    printf("容量 %d，实际可存 %d 个元素\n", CAP, CAP - 1);
    for (int i = 1; i <= 4; i++)
        printf("入队 %d -> %s\n", i, enqueue(i) ? "OK" : "FULL");
    int v = -1;
    printf("出队 -> %d\n", dequeue(&v) ? v : -1);
    printf("再入队 5 -> %s\n", enqueue(5) ? "OK" : "FULL");
    printf("剩余依次出队:");
    while (dequeue(&v)) printf(" %d", v);
    printf("\n");
    return 0;
}
